import os


def _list_files(path: str = ".") -> list:
    return os.listdir(path)


def _read_file(path: str) -> str:
    with open(path, "r") as f:
        return f.read()


def _count_lines(path: str) -> str:
    with open(path, "r") as f:
        return str(len(f.read().splitlines()))


TOOLS = {
    "list_files": _list_files,
    "read_file": _read_file,
    "count_lines": _count_lines,
}


def execute_tool(name: str, args: dict) -> str:
    tool = TOOLS.get(name)
    if tool is None:
        return f"Error: unknown tool '{name}'"
    return tool(**args)


# Test
try:
    result = execute_tool("count_lines", {"path": "test.txt"})
except (FileNotFoundError, OSError):
    result = None

print(f"Tool registry with {len(TOOLS)} tools and a working dispatcher")
